CREATE DATABASE sales_analytics;
USE sales_analytics;

CREATE TABLE sales_source (
    sale_id INT PRIMARY KEY AUTO_INCREMENT,
    order_id INT,
    customer_id INT,
    product_id INT,
    sale_date DATE,
    quantity INT,
    unit_price DECIMAL(10,2),
    total_amount DECIMAL(12,2)
);

